<script setup>
import { reactive } from 'vue'
import { Head, useForm } from '@inertiajs/vue3'
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'
const props=defineProps({orders:Array})
const selected=reactive({}), names=reactive({})
props.orders.forEach(order=>{selected[order.id]=[];names[order.id]=''})
function pack(order){useForm({work_item_ids:selected[order.id],group_name:names[order.id]}).post(route('man.staff.finishing-packaging.package-group.store',order.id),{preserveScroll:true,onSuccess:()=>{selected[order.id]=[];names[order.id]=''}})}
</script>
<template><Head title="Finishing Packing"/><AuthenticatedLayout><main class="mx-auto max-w-6xl space-y-5 p-4 sm:p-6"><header class="rounded-3xl bg-gradient-to-r from-amber-700 to-orange-600 p-6 text-white"><p class="text-xs font-black uppercase tracking-widest">Finishing Packer</p><h1 class="text-2xl font-black">Pack by JO and Fabric Code Group</h1><p class="mt-1 text-sm text-amber-100">Select the rolls that belong together. Every roll must be included in a packed group before supervisor handoff.</p></header><p v-if="!orders.length" class="rounded-2xl border border-dashed p-10 text-center text-slate-500">No quality-approved JO is waiting for packing.</p><section v-for="order in orders" :key="order.id" class="rounded-2xl border bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900"><h2 class="text-xl font-black">{{ order.jo_number }} · {{ order.items.length }} rolls ready</h2><div class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><label v-for="item in order.items" :key="item.id" class="flex items-center gap-2 rounded-lg border p-3 text-sm dark:border-zinc-700"><input v-model="selected[order.id]" type="checkbox" :value="item.id"/><span class="font-mono font-bold">{{ item.code }}</span><span>{{ item.weight }} kg · {{ item.yarn_type }}</span></label></div><div class="mt-4 flex flex-wrap gap-2"><input v-model="names[order.id]" placeholder="Group name (optional)" class="rounded-lg border p-2 text-sm"/><button @click="pack(order)" :disabled="!selected[order.id].length" class="rounded-lg bg-amber-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-40">Pack selected rolls together</button></div></section></main></AuthenticatedLayout></template>
